#!/usr/bin/env node
/**
 * A LAB VERSION BECOMES TEX'S CONFIG (Dev2, 2026-11-13: "I want the config generated by the lab to become the
 * production code, and to be the only source of truth").
 *
 * Reads a saved Lab version's graph (the JSON the Lab keeps in `texLabVersions.graph`) and writes it into
 * `packages/shared/src/texConfig.json`, one step and one wire per line, then regenerates tex.md's drawing and table and the map every Tex agent reads (`tex-architecture.mjs`). The
 * Lab promote workflow runs this on a branch of its own and opens the pull request; the pull request's gates decide.
 *
 * Refused, with the reason, rather than written: a graph whose steps or wires are malformed, a wire to a step that is
 * not there, a provisional wire whose `unless` drops `firstLook` or `sms` (the same check CI runs), a step on a model
 * the config's table has no gateway id for (a model added in the Lab only), or a step the gateway has no code for
 * (a new id: merge its code to main first, on the shelf, `texNodeShelf.json`; Dev2, 2026-11-16: "create the node
 * inside the code first and merge it to main"), or an edit to a module whose words are not a prompt module's
 * (a code module, a chat view, a step's own instructions: those change in code).
 *
 * Prompt words are promoted too (Dev2, 2026-11-14: the words live "in the repo, beside the config"): a version's text
 * for a prompt module, `p-<name>`, is written to `packages/shared/src/texPrompt/<name>.md` and the generated words
 * file is rebuilt, so the pull request's fingerprints show the changed prompt and the replay gate runs. A new
 * `p-<name>` module with words is a new file; which steps read it, and where, is the steps' context in the config.
 *
 *   node scripts/tex-lab-promote.mjs <graph.json> --base <stamp> --made <ms> [--summary <file>] [--picks <file>] [--clashes <file>]
 *                                                          merge the draft's own changes onto main (Promote); --picks
 *                                                          settles clashes ({ "<what>": "main" | "draft" }), --clashes
 *                                                          writes a refusal's clashes as JSON for the Lab to pick from
 *   node scripts/tex-lab-promote.mjs <graph.json>          write the graph as it is (a Lab Run on a branch's code)
 *   node scripts/tex-lab-promote.mjs <graph.json> --check  only say whether it would be refused
 *   node scripts/tex-lab-promote.mjs --self-test
 */
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { CONFIG, MODULE as MAP_MODULE, PAGE, moduleFor as mapModuleFor, pageFor } from "./tex-architecture.mjs";
import { clashText, findBase, mergeOntoMain, picksOf, sideAt } from "./tex-lab-merge.mjs";
import { FOLDER as PROMPT_FOLDER, MODULE as PROMPT_MODULE, moduleFor as promptModuleFor, wordsOf } from "./tex-prompt-module.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const ID = /^[a-z][A-Za-z0-9_-]{0,30}$/;
// The wire modes, efforts and migrations are the schema's (`texConfigSchema.cjs`).
const SCHEMA = createRequire(import.meta.url)("../packages/shared/src/texConfigSchema.cjs");
const MODES = new Set(SCHEMA.MODES);
const EFFORTS = new Set(SCHEMA.EFFORTS);
const PROMPT_KEY = /^p-([a-z][a-z0-9-]{0,47})$/;
const MAX_WORDS = 40_000;
/** Nodes merged but not wired (Dev2, 2026-11-16). */
export const SHELF = "packages/shared/src/texNodeShelf.json";

/**
 * The prompt words a version's module edits make over the current words, `{ words }` (only the modules it changes),
 * or `{ refused }`. An edit with no text (a renamed label, a cache flag) changes no words and is left out.
 */
export function wordsFrom(modules, currentWords) {
  const words = {};
  for (const [key, edit] of Object.entries(modules ?? {})) {
    if (!edit || typeof edit !== "object" || typeof edit.text !== "string") continue;
    const name = PROMPT_KEY.exec(key)?.[1];
    if (name === undefined) {
      if (edit.text.trim() === "") continue;
      return { refused: `it changes the words of "${key}", which is not a prompt module: that text is built in code, so change it on a branch` };
    }
    const text = edit.text.replace(/^\uFEFF/, "").trim();
    if (text === "") return { refused: `it empties the prompt module "${name}": take it out of the steps' context instead` };
    if (text.length > MAX_WORDS) return { refused: `the prompt module "${name}" is longer than ${MAX_WORDS} characters` };
    if (/^---\r?\n/.test(text)) return { refused: `the prompt module "${name}" starts with front matter, which Tex would be sent` };
    if (text !== currentWords[name]) words[name] = text;
  }
  return { words };
}

/**
 * The config a graph makes over the current one, `{ config, words, unshelved }`, or `{ refused }`. A step on the shelf
 * (`shelf`: ids whose code is merged but not wired) may join; `unshelved` names the ones that did, which come off it.
 */
export function configFrom(graph, current, currentWords = {}, shelf = []) {
  const refuse = (why) => ({ refused: why });
  if (!graph || !Array.isArray(graph.nodes) || !Array.isArray(graph.edges)) return refuse("the version has no steps and wires");
  // A version saved under an older shape is brought to the current one first (`texConfigSchema.cjs` MIGRATIONS).
  graph = SCHEMA.migrateGraph(graph);
  const madeWords = wordsFrom(graph.modules, currentWords);
  if (madeWords.refused) return madeWords;
  const known = new Set(current.nodes.map((n) => n.id));
  const shelved = new Set(shelf);
  const ids = new Set();
  for (const n of graph.nodes) {
    if (!n || typeof n !== "object" || typeof n.id !== "string" || !ID.test(n.id)) return refuse(`a step has no usable id (${JSON.stringify(n?.id)})`);
    if (ids.has(n.id)) return refuse(`step "${n.id}" is there twice`);
    ids.add(n.id);
    if (!known.has(n.id) && !shelved.has(n.id)) return refuse(`step "${n.id}" is new: the gateway has no code for it yet, so merge its code to main first, on the shelf (texNodeShelf.json)`);
    if (typeof n.model !== "string" || (n.model !== "code" && typeof current.models[n.model] !== "string")) return refuse(`step "${n.id}" runs on "${n.model}", which has no gateway model id in Tex's config`);
    if (n.effort !== undefined && !EFFORTS.has(n.effort)) return refuse(`step "${n.id}" has effort "${n.effort}"`);
    if (typeof n.on !== "boolean") return refuse(`step "${n.id}" is neither on nor off`);
  }
  for (const id of known) if (!ids.has(id)) return refuse(`step "${id}" is gone: the gateway still runs it, so turn it off instead of deleting it`);
  for (const e of graph.edges) {
    if (!e || !ids.has(e.from) || !ids.has(e.to)) return refuse(`a wire joins a step that is not there (${e?.from} → ${e?.to})`);
    if (!MODES.has(e.mode) || !Array.isArray(e.when) || !e.when.every((w) => typeof w === "string")) return refuse(`the wire ${e.from} → ${e.to} is malformed`);
    if (e.rounds !== undefined && !(Number.isInteger(e.rounds) && e.rounds > 0 && e.rounds <= 100)) return refuse(`the wire ${e.from} → ${e.to} has rounds that are not a whole number from 1 to 100`);
    // A provisional wire's allow (Dev2, 2026-11-17): what its step may do before the go.
    if (e.allow !== undefined && !(e.mode === "provisional" && (e.allow === "read" || e.allow === "revertible"))) return refuse(`the wire ${e.from} → ${e.to} has allow "${e.allow}": only a provisional wire has one, "read" or "revertible"`);
    if (e.unless !== undefined && !(e.mode === "provisional" && Array.isArray(e.unless) && e.unless.every((fact) => SCHEMA.START_FACTS.includes(fact)))) return refuse(`the wire ${e.from} → ${e.to} has unless ${JSON.stringify(e.unless)}: only a provisional wire has one, a list of ${SCHEMA.START_FACTS.join(", ")}`);
    // The same hold check CI runs (`provisionalHoldProblems`): a Promote cannot drop firstLook or sms.
    if (e.mode === "provisional") {
      const missing = SCHEMA.provisionalHoldProblems([e]);
      if (missing.length) return refuse(missing.join("; "));
    }
  }
  // In the order main has them, so a promotion's diff shows only what changed.
  const order = new Map(current.nodes.map((n, i) => [n.id, i]));
  // A step off the shelf goes after main's, in the version's order.
  const at = (n) => order.get(n.id) ?? current.nodes.length + graph.nodes.indexOf(n);
  const nodes = [...graph.nodes].sort((a, b) => at(a) - at(b));
  // Every prompt module a step reads must have words, here or in this version.
  for (const n of nodes) {
    for (const entry of n.ctx ?? []) {
      const name = PROMPT_KEY.exec(entry)?.[1];
      if (name !== undefined && typeof currentWords[name] !== "string" && typeof madeWords.words[name] !== "string") return refuse(`step "${n.id}" reads the prompt module "${name}", which has no words`);
    }
  }
  // Wires in the order main has them too (the Lab unfolds a group's wires in its own order), new ones last.
  const wireKey = (e) => `${e.from}>${e.to}>${e.mode}`;
  const wireOrder = new Map(current.edges.map((e, i) => [wireKey(e), i]));
  const edges = graph.edges.map(({ from, to, mode, when, rounds, allow, unless }) => ({ from, to, mode, when, ...(rounds !== undefined ? { rounds } : {}), ...(allow !== undefined ? { allow } : {}), ...(unless !== undefined ? { unless } : {}) })).map((e, i) => ({ e, at: wireOrder.get(wireKey(e)) ?? current.edges.length + i })).sort((a, b) => a.at - b.at).map(({ e }) => e);
  // The draft's own group boxes over main's (the `group` edit), only for groups some step names.
  let groups = current.groups;
  if (graph.groups && typeof graph.groups === "object") {
    groups = { ...(current.groups ?? {}) };
    for (const [id, info] of Object.entries(graph.groups)) {
      if (!ID.test(id) || !info || typeof info !== "object" || typeof info.label !== "string") return refuse(`group "${id}" has no label`);
      groups[id] = Object.fromEntries(["label", "goal", "icon", "x", "y", "parent"].filter((k) => info[k] !== undefined).map((k) => [k, info[k]]));
    }
    // A group some step names, and every group around it (groups nest: Dev2, 2026-11-16), is kept.
    const named = new Set(nodes.map((n) => n.group).filter(Boolean));
    for (const id of [...named]) for (let up = groups[id]?.parent; up && !named.has(up); up = groups[up]?.parent) named.add(up);
    for (const id of Object.keys(groups)) if (!named.has(id) && !(current.groups ?? {})[id]) delete groups[id];
  }
  return { config: { ...current, nodes, edges, ...(groups ? { groups } : {}) }, words: madeWords.words, unshelved: nodes.map((n) => n.id).filter((id) => shelved.has(id)) };
}

/** The config file's text: the head as JSON, then one step and one wire per line. */
export function configText(config) {
  const lines = (a) => "[\n" + a.map((x) => "    " + JSON.stringify(x)).join(",\n") + "\n  ]";
  const models = JSON.stringify(config.models, null, 4).replace(/\n}$/, "\n  }");
  const groups = config.groups ? `\n  "groups": ${JSON.stringify(config.groups)},` : "";
  const browsers = config.browsers ? `\n  "browsers": ${JSON.stringify(config.browsers)},` : "";
  return `{\n  "texConfig": ${config.texConfig},\n  "about": ${JSON.stringify(config.about)},\n  "models": ${models},${browsers}${groups}\n  "nodes": ${lines(config.nodes)},\n  "edges": ${lines(config.edges)}\n}\n`;
}

/**
 * A draft merged onto main from the base it was found on, with the line Promote prints. A draft refused against its
 * own base (or once merged) answers `{ refused }` and no note: it has no `kept` to count, and reading one crashed
 * Promote (draft vmwmxtcxerrji, 2026-11-18).
 */
export function mergeDraft({ graph, found, base, main, shelf = [], picks = {} }) {
  const merged = mergeOntoMain({ graph, base, main, shelf, configFrom, picks });
  if (merged.refused || merged.clashes?.length) return merged;
  const kept = merged.kept.length;
  const note = `merged onto main from ${String(found.commit).slice(0, 7)}${found.guessed ? " (taken from when the draft was made: it was saved before drafts kept their base)" : ""}: ${kept} change${kept === 1 ? "" : "s"} of its own, ${merged.theirs} of main's since kept`;
  return { ...merged, note };
}

function selfTest() {
  const expect = (cond, what) => {
    if (!cond) throw new Error(`self-test: ${what}`);
  };
  const current = JSON.parse(readFileSync(join(ROOT, CONFIG), "utf8"));
  const words = wordsOf(ROOT);
  expect(configText(current) === readFileSync(join(ROOT, CONFIG), "utf8"), "the committed config is not in the promote format");
  const same = configFrom({ nodes: current.nodes, edges: current.edges }, current, words);
  expect(same.config && configText(same.config) === configText(current), "main's own graph does not promote to main's config");
  const graph = () => JSON.parse(JSON.stringify({ nodes: current.nodes, edges: current.edges }));
  // A send-back wire's rounds (how many times it may send work back) is config, and survives a promotion.
  const g0 = graph();
  const loop = g0.edges.find((e) => e.mode === "loop");
  if (loop) {
    loop.rounds = 7;
    expect(configFrom(g0, current, words).config?.edges.find((e) => e.from === loop.from && e.to === loop.to && e.mode === "loop")?.rounds === 7, "a loop wire's rounds were lost");
    loop.rounds = 0;
    expect(/rounds/.test(configFrom(g0, current, words).refused ?? ""), "a wire with rounds 0 passed");
  }
  // A provisional wire, and its allow, is config too.
  const gp = graph();
  gp.edges.push({ from: "text", to: "doorStep", mode: "provisional", when: ["stop:running"], allow: "read", unless: ["firstLook", "sms"] });
  expect(configFrom(gp, current, words).config?.edges.find((e) => e.from === "text" && e.mode === "provisional")?.allow === "read", "a provisional wire's allow was lost");
  expect(configFrom(gp, current, words).config?.edges.find((e) => e.from === "text" && e.mode === "provisional")?.unless?.join() === "firstLook,sms", "a provisional wire's unless was lost");
  gp.edges[gp.edges.length - 1].allow = "anything";
  expect(/allow/.test(configFrom(gp, current, words).refused ?? ""), "a provisional wire with an unknown allow passed");
  gp.edges[gp.edges.length - 1].allow = "read";
  gp.edges[gp.edges.length - 1].unless = ["sideways"];
  expect(/unless/.test(configFrom(gp, current, words).refused ?? ""), "a provisional wire with an unknown unless passed");
  // firstLook and sms are required. Dropping either must be refused here, the same check CI runs, and logged.
  const dropHold = (fact) => {
    const g = graph();
    const wire = g.edges.find((e) => e.from === "triage" && e.mode === "provisional");
    wire.unless = wire.unless.filter((f) => f !== fact);
    const lines = [];
    const log = console.log;
    console.log = (line) => lines.push(String(line));
    let refused = "";
    try {
      refused = configFrom(g, current, words).refused ?? "";
    } finally {
      console.log = log;
    }
    return { refused, lines };
  };
  for (const fact of ["firstLook", "sms"]) {
    const dropped = dropHold(fact);
    expect(new RegExp(`provisional wire triage → doorStep is missing the hold ${fact}`).test(dropped.refused), `a provisional wire that drops ${fact} was promoted`);
    expect(dropped.lines.some((line) => line.includes("provisional_hold_refused") && line.includes(`"missing":"${fact}"`) && line.includes('"from":"triage"')), `dropping ${fact} was not logged`);
  }
  // A generator wire (starts a new run) is config too.
  const gg = graph();
  gg.edges.push({ from: "send", to: "text", mode: "generator", when: ["answer"] });
  expect(configFrom(gg, current, words).config?.edges.some((e) => e.mode === "generator" && e.to === "text"), "a generator wire was lost");
  const g1 = graph();
  g1.nodes.find((n) => n.id === "reviewer").effort = "medium";
  expect(configFrom(g1, current, words).config.nodes.find((n) => n.id === "reviewer").effort === "medium", "an effort change was lost");
  const g2 = graph();
  g2.nodes.push({ ...g2.nodes[0], id: "brandnew" });
  expect(/new/.test(configFrom(g2, current, words).refused ?? ""), "a step with no code passed");
  const g3 = graph();
  g3.nodes.find((n) => n.id === "fd").model = "custom-1";
  expect(/no gateway model id/.test(configFrom(g3, current, words).refused ?? ""), "a Lab-only model passed");
  const g4 = graph();
  g4.nodes = g4.nodes.filter((n) => n.id !== "selfreview");
  expect(/gone/.test(configFrom(g4, current, words).refused ?? ""), "a deleted step passed");
  const g5 = graph();
  g5.edges.push({ from: "fd", to: "nowhere", mode: "wait", when: ["*"] });
  expect(/not there/.test(configFrom(g5, current, words).refused ?? ""), "a wire to nowhere passed");
  const g6 = configFrom({ ...graph(), modules: { "p-rules": { text: `${words.rules}\n\nOne more rule.` } } }, current, words);
  expect(g6.words?.rules?.endsWith("One more rule."), "a prompt module's new words were lost");
  expect(Object.keys(configFrom({ ...graph(), modules: { "p-rules": { text: `${words.rules}\n` }, "p-tools": { tok: 9 } } }, current, words).words ?? {}).length === 0, "unchanged words were written");
  expect(/not a prompt module/.test(configFrom({ ...graph(), modules: { caps: { text: "x" } } }, current, words).refused ?? ""), "a code module's words passed");
  expect(/empties/.test(configFrom({ ...graph(), modules: { "p-rules": { text: " " } } }, current, words).refused ?? ""), "an emptied module passed");
  const g7 = graph();
  g7.nodes.find((n) => n.id === "fd").ctx.push("p-brand-new");
  expect(/no words/.test(configFrom(g7, current, words).refused ?? ""), "a step reading a module with no words passed");
  expect(configFrom({ ...g7, modules: { "p-brand-new": { text: "New words." } } }, current, words).words?.["brand-new"] === "New words.", "a new module's words were lost");
  // A shelf node (merged, not wired) may join; a new id with no code still may not.
  const g9 = graph();
  g9.nodes.push({ id: "shelved", label: "Shelved", model: "code", on: true });
  g9.edges.push({ from: g9.nodes[0].id, to: "shelved", mode: "background", when: ["*"] });
  expect(/new/.test(configFrom(g9, current, words).refused ?? ""), "a new step with no code passed");
  const off = configFrom(g9, current, words, ["shelved"]);
  expect(off.config?.nodes.at(-1)?.id === "shelved" && off.unshelved?.join() === "shelved", "a shelf node did not join the config last and come off the shelf");
  const g8 = graph();
  const bg = g8.edges.find((e) => e.mode === "background");
  bg.mode = "behind";
  expect(configFrom(g8, current, words).config?.edges.find((e) => e.from === bg.from && e.to === bg.to)?.mode === "background", "a version saved with the old \"behind\" wire did not promote as background");
  // A nested group keeps the group it sits in, and that group stays though no step names it directly.
  const g10 = graph();
  g10.groups = { outer: { label: "Outer" }, inner: { label: "Inner", parent: "outer" } };
  g10.nodes.find((n) => n.id === "fd").group = "inner";
  const nested = configFrom(g10, current, words).config;
  expect(nested?.groups?.inner?.parent === "outer" && nested?.groups?.outer?.label === "Outer", "a nested group lost the group it sits in");
  // A draft refused against its own base is refused, not a crash (draft vmwmxtcxerrji, 2026-11-18).
  const emptied = { ...graph(), modules: { [`p-${Object.keys(words)[0]}`]: { text: "" } } };
  let refusedMerge;
  try {
    refusedMerge = mergeDraft({ graph: emptied, found: { commit: "c02926e99ed6376", guessed: true }, base: { config: current, words }, main: { config: current, words } });
  } catch (error) {
    throw new Error(`self-test: a draft refused against its base crashed the merge (${error.message})`);
  }
  expect(typeof refusedMerge.refused === "string" && refusedMerge.note === undefined, "a draft refused against its base was not refused");
  const plain = mergeDraft({ graph: graph(), found: { commit: "abcdef0123456", guessed: false }, base: { config: current, words }, main: { config: current, words } });
  expect(!plain.refused && /^merged onto main from abcdef0: 0 changes of its own, 0 of main's since kept$/.test(plain.note ?? ""), `an unchanged draft's merge note was wrong (${plain.refused ?? plain.note})`);
  console.log("tex-lab-promote self-test: ok");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  if (args.includes("--self-test")) selfTest();
  else {
    const file = args.find((a, i) => !a.startsWith("--") && !["--base", "--made", "--main", "--summary", "--picks", "--clashes"].includes(args[i - 1]));
    if (!file) {
      console.error("usage: node scripts/tex-lab-promote.mjs <graph.json> [--check] | --self-test");
      process.exit(2);
    }
    let graph;
    try {
      graph = JSON.parse(readFileSync(file, "utf8"));
    } catch (error) {
      console.error(`tex-lab-promote: refused: the version's graph is not JSON (${error.message})`);
      process.exit(1);
    }
    const current = JSON.parse(readFileSync(join(ROOT, CONFIG), "utf8"));
    const shelf = JSON.parse(readFileSync(join(ROOT, SHELF), "utf8"));
    const shelfIds = Object.keys(shelf.nodes ?? {});
    // A promotion is a merge onto main (Dev2, 2026-11-17): the draft's own changes since the main it started from
    // (`--base <stamp>`, `--made <ms>`), never its whole graph (`tex-lab-merge.mjs`). Without them (the Lab's Run on a
    // branch's code) the graph is written as it is, as before.
    const flag = (name) => {
      const i = args.indexOf(name);
      return i >= 0 ? args[i + 1] : undefined;
    };
    let made;
    let note = "";
    if (flag("--base") !== undefined || flag("--made") !== undefined) {
      const found = findBase({ stamp: flag("--base"), made: Number(flag("--made")) }, flag("--main") ?? "HEAD");
      if (!found) {
        console.error("tex-lab-promote: refused: the main this draft was made from is not on main any more, so its own changes can't be told from main's; make a fresh draft from main and redo them");
        process.exit(1);
      }
      let picks = {};
      if (flag("--picks")) {
        try {
          picks = picksOf(JSON.parse(readFileSync(flag("--picks"), "utf8")));
        } catch {
          picks = {};
        }
      }
      const merged = mergeDraft({ graph, found, base: sideAt(found.commit), main: { config: current, words: wordsOf(ROOT) }, shelf: shelfIds, picks });
      if (merged.clashes?.length) {
        if (flag("--clashes")) writeFileSync(flag("--clashes"), JSON.stringify(merged.clashes.slice(0, 50).map((c) => ({ what: c.what.slice(0, 300), main: String(c.main).slice(0, 200), draft: String(c.draft).slice(0, 200), pick: c.pick === true }))));
        console.error(`tex-lab-promote: refused: ${clashText(merged.clashes, found.commit)}`);
        process.exit(1);
      }
      if (merged.refused) {
        console.error(`tex-lab-promote: refused: ${merged.refused}`);
        process.exit(1);
      }
      made = merged;
      note = merged.note;
      const summary = flag("--summary");
      if (summary && !args.includes("--check")) writeFileSync(summary, JSON.stringify({ base: found.commit, guessed: found.guessed, kept: merged.kept, theirs: merged.theirs }));
    } else made = configFrom(graph, current, wordsOf(ROOT), shelfIds);
    if (made.refused) {
      console.error(`tex-lab-promote: refused: ${made.refused}`);
      process.exit(1);
    }
    if (!args.includes("--check")) {
      writeFileSync(join(ROOT, CONFIG), configText(made.config));
      // The drawing and the map every Tex agent reads are the config's, so a promoted wire changes Tex's prompts and the replay gate runs on it.
      writeFileSync(join(ROOT, PAGE), pageFor(readFileSync(join(ROOT, PAGE), "utf8"), made.config));
      writeFileSync(join(ROOT, MAP_MODULE), mapModuleFor(made.config));
      for (const [name, text] of Object.entries(made.words)) writeFileSync(join(ROOT, PROMPT_FOLDER, `${name}.md`), `${text}\n`);
      writeFileSync(join(ROOT, PROMPT_MODULE), promptModuleFor(wordsOf(ROOT)));
      // A shelf node now wired comes off the shelf in the same pull request.
      if (made.unshelved.length > 0) {
        for (const id of made.unshelved) delete shelf.nodes[id];
        writeFileSync(join(ROOT, SHELF), `${JSON.stringify(shelf, null, 2)}\n`);
      }
    }
    const changed = Object.keys(made.words);
    console.log(`tex-lab-promote: ${args.includes("--check") ? "would write" : "wrote"} ${CONFIG}, ${PAGE}'s drawing and table and ${MAP_MODULE}${changed.length > 0 ? `, and the words of ${changed.join(", ")}` : ""}${note ? `; ${note}` : ""}`);
  }
}
